// ── FREESPACE EXPLOSIONS AND MISSILE TRAILS (v216, Paket E6/E8) ──
// Silvio chose variant C with the flash of B (v216_entwurf_effekte.png):
// the explosion animations of MediaVP 5.0.2 (MV_Effects_1/data/effects,
// sheets built by fx/mkfxsheets.py) instead of drawn fireballs, sized to the
// ship that dies, and the bright flash with a ring at the end of a capital
// ship. Missiles leave the FS trail (MissileTrail01) with a little smoke.
//   exp05: secondaries, fighters, every fireball of the game (spawnFireball)
//   exp20: the big blast of a capital ship, about as wide as her hull
//   smoke: ParticleSmoke01, the smoke clouds (spawnSmoke)
// Fire is drawn additively ('lighter', the frames lie on black), smoke
// keeps its alpha. All timings count game steps, so a pause holds them.
const FX_SHEET_META = {
  exp05: {n: 47, cols: 8, cell: 128},
  exp20: {n: 38, cols: 8, cell: 128},
  smoke: {n: 18, cols: 6, cell: 128}
};
const FX_SHEET_B64 = {
  exp05: '',
  exp20: '',
  smoke: '',
  trail: ''
};
const FX_IMG = {};
let FX_OK = null;
function fxLoad(){
  if(FX_OK !== null || typeof Image === 'undefined') return;
  FX_OK = false;
  try{
    let left = 0;
    for(const k in FX_SHEET_B64){
      const im = new Image(); left++;
      im.onload = function(){ if(--left === 0) FX_OK = true; };
      im.onerror = function(){ FX_OK = false; };
      im.src = 'data:image/webp;base64,' + FX_SHEET_B64[k];
      FX_IMG[k] = im;
    }
  }catch(e){ FX_OK = false; }
}
function fxReady(){ if(FX_OK === null) fxLoad(); return FX_OK === true; }

// The animations on the field: {k, x, y, d (width in world units), t0, dur
// (steps), rot, a (alpha)}. Their own list with its own cap, so a busy
// fight trimming PARTS never cuts a ship's blast short.
let FX_ANIMS = [];
const FX_ANIM_CAP = 260;
const FX_FB_K = 2.6;            // an animation frame's width per fireball radius
function fxFire(k, x, y, d, dur, a){
  if(FX_ANIMS.length >= FX_ANIM_CAP){
    // drop the smallest one that is furthest along, never a big blast
    let wi = -1, wv = Infinity;
    for(let i = 0; i < FX_ANIMS.length; i++){ const f = FX_ANIMS[i]; const v = f.d*(1 - (fc - f.t0)/f.dur); if(v < wv){ wv = v; wi = i; } }
    if(wi < 0 || FX_ANIMS[wi].d > d) return;
    FX_ANIMS.splice(wi, 1);
  }
  FX_ANIMS.push({k: k, x: x, y: y, d: d, t0: fc, dur: Math.max(4, dur|0), rot: Math.random()*Math.PI*2, a: (a == null ? 1 : a)});
}
// the flash of B: a white-hot glow that swells fast and dies away
function fxFlash(x, y, r, dur){
  fxFire('flash', x, y, r, dur, 1);
}
function tickFxAnims(){
  for(let i = FX_ANIMS.length - 1; i >= 0; i--) if(fc - FX_ANIMS[i].t0 >= FX_ANIMS[i].dur) FX_ANIMS.splice(i, 1);
}
// a frame of a sheet, centred at (x, y), d wide
function fxFrame(k, f, x, y, d, rot){
  const m = FX_SHEET_META[k], im = FX_IMG[k];
  const i = Math.max(0, Math.min(m.n - 1, f|0)), c = m.cell;
  const sx = (i % m.cols)*c, sy = ((i/m.cols)|0)*c;
  if(rot){ ctx.save(); ctx.translate(x, y); ctx.rotate(rot); ctx.drawImage(im, sx, sy, c, c, -d/2, -d/2, d, d); ctx.restore(); }
  else ctx.drawImage(im, sx, sy, c, c, x - d/2, y - d/2, d, d);
}
const FX_MIN_PX = 12;           // an explosion is never smaller on the screen
function drawFxAnims(){
  if(!FX_ANIMS.length || !fxReady()) return;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const dMin = FX_MIN_PX/CAM.z;
  for(const f of FX_ANIMS){
    const p = Math.max(0, Math.min(0.999, (fc - f.t0)/f.dur));
    if(f.k === 'flash'){
      // up in the first fifth, then away
      const up = Math.min(1, p/0.18), al = up*(1 - Math.max(0, (p - 0.18)/0.82));
      ctx.globalAlpha = 1;
      glowAt(f.x, f.y, f.d*(0.55 + 0.45*up), f.d*(0.55 + 0.45*up), '#ffd9a8', al*0.95, 0.75);
      continue;
    }
    ctx.globalAlpha = f.a;
    fxFrame(f.k, p*FX_SHEET_META[f.k].n, f.x, f.y, Math.max(dMin, f.d), f.rot);
  }
  ctx.restore();
}
// FS smoke instead of the grey disc: one cloud of PARTS (type 'smoke')
function drawFxSmoke(p, a, r){
  if(!fxReady()) return false;
  const tp = 1 - p.life/p.ml;
  if(p.rot == null) p.rot = Math.random()*Math.PI*2;
  ctx.save();
  ctx.globalCompositeOperation = 'source-over';
  ctx.globalAlpha = Math.max(0, a)*(p.trail ? 0.30 : 0.55);
  fxFrame('smoke', tp*FX_SHEET_META.smoke.n, p.x, p.y, r*2.4, p.rot);
  ctx.restore();
  return true;
}

// A ship's length and axis on the field (world units), for blasts that run
// along her hull.
function fxHull(src, fallback){
  const im = src && IMGS[src.img];
  const L = im ? im.width*src.sc : fallback, B = im ? im.height*src.sc : fallback*0.3;
  return {L: Math.max(8, L), B: Math.max(4, B), c: Math.cos((src && src.ang) || 0), s: Math.sin((src && src.ang) || 0)};
}
// a point on her hull: t along her length (-0.5..0.5), u across (-0.5..0.5)
function fxOnHull(h, x, y, t, u){
  return {x: x + h.c*t*h.L - h.s*u*h.B, y: y + h.s*t*h.L + h.c*u*h.B};
}

// ── missile trails ──
// Every missile keeps the points it passed (_tr, world units, game step);
// the trail is the FS texture laid along them, thin at the missile and
// wider and fainter behind it, with a puff of smoke now and then.
const TRAIL_LIFE = 55;          // steps a point of the trail lasts
const TRAIL_STEP = 3;           // a new point every few steps
function trailFeed(b){
  const t = b._tr || (b._tr = []);
  const last = t[t.length - 1];
  if(!last || fc - last.f >= TRAIL_STEP){
    t.push({x: b.x, y: b.y, f: fc});
    // smoke: small FS clouds that drift and fade (a few, so PARTS stays calm)
    if(fxReady() && Math.random() < 0.35 && PARTS.length < 560)
      PARTS.push({type: 'smoke', trail: true, x: b.x, y: b.y, vx: (Math.random() - 0.5)*0.3, vy: (Math.random() - 0.5)*0.3,
                  life: 40 + Math.random()*30, ml: 0, sz: (b.w || 8)*0.55*ordG(), v: 60});
  }
  while(t.length && fc - t[0].f > TRAIL_LIFE) t.shift();
}
function drawTrail(b, headW){
  if(paused !== true) trailFeed(b);
  const t = b._tr;
  if(!t || t.length < 1 || !fxReady()) return;
  const im = FX_IMG.trail;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  // from the missile back: segments of the texture, each a little wider
  // and fainter than the one before
  let px = b.x, py = b.y;
  for(let i = t.length - 1; i >= 0; i--){
    const q = t[i], age = Math.min(1, (fc - q.f)/TRAIL_LIFE);
    const dx = px - q.x, dy = py - q.y, len = Math.hypot(dx, dy);
    if(len > 0.5){
      const w = headW*(0.45 + 1.3*age), al = 0.85*(1 - age);
      ctx.save();
      ctx.translate(q.x, q.y); ctx.rotate(Math.atan2(dy, dx));
      ctx.globalAlpha = Math.max(0, al);
      ctx.drawImage(im, 0, 0, im.width, im.height, -0.5, -w/2, len + 1, w);
      ctx.restore();
    }
    px = q.x; py = q.y;
  }
  ctx.restore();
}
// load the sheets with the page, so the first blast of a mission has them
if(typeof document !== 'undefined') try{ fxLoad(); }catch(e){}
